/* ALBAM09 V11 / premium regional venue spotlight.
 * Static first cards are generated by build-search-pages; JS enhances navigation.
 * Venue photos are existing site thumbnails, never generated placeholders.
 */
(function(){
  'use strict';
  if(window.__ALBAM09_V11_SPOTLIGHT__)return;
  window.__ALBAM09_V11_SPOTLIGHT__=true;
  const INTERVAL=3650;
  const DURATION=560;
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const attr=s=>esc(s);
  const prefersReduced=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const venueLink=v=>'/map/'+encodeURIComponent(v.board)+'/?venue='+encodeURIComponent(v.slug);
  function cardMarkup(v,index,total){
    const img=String(v.image||'');
    return '<a class="ab09-spotlight" href="'+attr(venueLink(v))+'" aria-label="'+attr(v.name)+' 지도 위치 보기">'+
      '<span class="ab09-spotlight__media"><img src="'+attr(img)+'" alt="'+attr(v.name)+' 등록 이미지" loading="lazy" decoding="async"></span>'+
      '<span class="ab09-spotlight__veil" aria-hidden="true"></span>'+
      '<span class="ab09-spotlight__content">'+
        '<span class="ab09-spotlight__eyebrow">VENUE <b>'+String(index+1).padStart(2,'0')+' / '+String(total).padStart(2,'0')+'</b></span>'+
        '<strong class="ab09-spotlight__name">'+esc(v.name)+'</strong>'+
        '<span class="ab09-spotlight__cta">지도에서 보기 <span aria-hidden="true">↗</span></span>'+
      '</span></a>';
  }
  function mount(){
    const data=Array.isArray(window.PUBLIC_VENUES)?window.PUBLIC_VENUES:[];
    document.querySelectorAll('[data-region-preview]').forEach(function(shell,idx){
      const board=shell.getAttribute('data-region-preview');
      const items=data.filter(v=>v.board===board&&v.slug&&v.name);
      const target=shell.querySelector('[data-preview-item]');
      if(!target||!items.length)return;
      target.classList.add('ab09-spotlight-host');
      target.setAttribute('aria-label','업소 사진 슬라이더: '+board);
      target.innerHTML='<div class="ab09-venue-rail" role="group" aria-roledescription="슬라이더"></div>'+
        '<div class="ab09-spotlight__controls"><button type="button" class="ab09-spotlight__prev" aria-label="이전 업소 보기">‹</button><button type="button" class="ab09-spotlight__next" aria-label="다음 업소 보기">›</button></div>';
      const rail=target.querySelector('.ab09-venue-rail');
      const buttons=target.querySelectorAll('button');
      let index=idx%items.length;
      let busy=false,hold=false,timer=0,resetTimer=0,gestureStart=null,suppressClickUntil=0;
      function draw(){
        const next=(index+1)%items.length;
        rail.innerHTML=cardMarkup(items[index],index,items.length)+(items.length>1?cardMarkup(items[next],next,items.length):'');
        buttons.forEach(b=>b.disabled=items.length<2);
        shell.setAttribute('data-active-venue',items[index].slug);
      }
      function cancel(){if(timer)clearTimeout(timer);timer=0;}
      function schedule(){cancel();if(hold||busy||items.length<2||prefersReduced||document.hidden)return;timer=setTimeout(()=>slide(1),INTERVAL);}
      function instant(delta){
        cancel();if(resetTimer)clearTimeout(resetTimer);
        index=(index+delta+items.length)%items.length;
        busy=false;rail.classList.remove('is-sliding');rail.style.removeProperty('--ab09-slide-shift');
        draw();schedule();
      }
      function slide(delta){
        if(items.length<2||busy)return;
        if(delta<0){instant(-1);return;}
        cancel();busy=true;
        const first=rail.querySelector('a');
        const computed=getComputedStyle(rail);
        const space=parseFloat(computed.gap||computed.columnGap)||9;
        const distance=first?first.getBoundingClientRect().width+space:target.clientWidth*.83;
        rail.style.setProperty('--ab09-slide-shift',distance+'px');
        rail.classList.add('is-sliding');
        resetTimer=setTimeout(function(){
          rail.classList.remove('is-sliding');rail.style.transition='none';
          index=(index+1)%items.length;draw();
          void rail.offsetWidth;rail.style.transition='';busy=false;
          schedule();
        },prefersReduced?0:DURATION+35);
      }
      function pause(){hold=true;cancel();}
      function resume(){hold=false;schedule();}
      buttons[0].addEventListener('click',e=>{e.stopPropagation();instant(-1);});
      buttons[1].addEventListener('click',e=>{e.stopPropagation();slide(1);});
      shell.addEventListener('mouseenter',pause);
      shell.addEventListener('mouseleave',resume);
      shell.addEventListener('focusin',pause);
      shell.addEventListener('focusout',e=>{if(!shell.contains(e.relatedTarget))resume();});
      target.addEventListener('touchstart',e=>{gestureStart=e.touches[0]?.clientX??null;pause();},{passive:true});
      target.addEventListener('click',e=>{if(Date.now()<suppressClickUntil){e.preventDefault();e.stopPropagation();}},{capture:true});
      target.addEventListener('touchend',e=>{
        const end=e.changedTouches[0]?.clientX??null;
        if(gestureStart!==null&&end!==null){const dx=end-gestureStart;if(Math.abs(dx)>36){suppressClickUntil=Date.now()+650;if(dx<0)slide(1);else instant(-1);}}
        gestureStart=null;setTimeout(()=>{if(!shell.matches(':hover')&&!shell.contains(document.activeElement))resume();},1600);
      },{passive:true});
      draw();schedule();
      window.addEventListener('pagehide',()=>{cancel();if(resetTimer)clearTimeout(resetTimer);},{once:true});
    });
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();
})();
